export default {
  id: 'result-panel',
  name: 'Result Panel',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'api',
      api: {
        mount: 'panel',
        router: (_req: unknown, res: { json(value: unknown): void }) =>
          res.json({ title: 'Panel', html: '<p>value=29</p>' })
      }
    });
  }
};
